-- Editor runtime patches are intentionally not fabricated here because their exact SQL
-- source is not present in the uploaded checkpoint tree.

create or replace function public.add_inventory_item_authorized(p_container_id uuid,p_item_id uuid,p_quantity numeric default 1,p_item_instance_id uuid default null,p_actor_life_id uuid default null,p_metadata jsonb default '{}') returns uuid language plpgsql security definer set search_path=public,pg_temp as $f$ begin if auth.uid() is null then raise exception 'inventory_add_auth_required'; end if; if p_actor_life_id is null then raise exception 'inventory_add_actor_required'; end if; if not exists(select 1 from public.user_lives ul where ul.user_id=auth.uid() and ul.life_id=p_actor_life_id) then raise exception 'inventory_add_actor_not_owned'; end if; if not public.can_mutate_container(p_container_id,p_actor_life_id,'use') then raise exception 'inventory_add_not_authorized'; end if; return public.add_inventory_item(p_container_id,p_item_id,p_quantity,p_item_instance_id,p_metadata); end;$f$;
create or replace function public.consume_inventory_item_authorized(p_container_id uuid,p_item_id uuid,p_quantity numeric default 1,p_item_instance_id uuid default null,p_actor_life_id uuid default null,p_reason text default null,p_metadata jsonb default '{}') returns uuid language plpgsql security definer set search_path=public,pg_temp as $f$ begin if auth.uid() is null then raise exception 'inventory_consume_auth_required'; end if; if p_actor_life_id is null then raise exception 'inventory_consume_actor_required'; end if; if not exists(select 1 from public.user_lives ul where ul.user_id=auth.uid() and ul.life_id=p_actor_life_id) then raise exception 'inventory_consume_actor_not_owned'; end if; if not public.can_mutate_container(p_container_id,p_actor_life_id,'use') then raise exception 'inventory_consume_not_authorized'; end if; return public.consume_inventory_item(p_container_id,p_item_id,p_quantity,p_item_instance_id,p_actor_life_id,p_reason,p_metadata); end;$f$;
create or replace function public.transfer_inventory_authorized(p_source_container_id uuid,p_destination_container_id uuid,p_item_id uuid,p_quantity numeric,p_actor_life_id uuid default null,p_transfer_type text default 'move',p_reason text default null,p_metadata jsonb default '{}') returns uuid language plpgsql security definer set search_path=public,pg_temp as $f$ declare uid uuid:=auth.uid(); v_item public.items%rowtype; v_src public.containers%rowtype; v_dst public.containers%rowtype; v_src_qty numeric; v_dst_qty numeric; begin if uid is null then raise exception 'inventory_transfer_auth_required'; end if; if p_actor_life_id is null then raise exception 'inventory_transfer_actor_required'; end if; if not exists(select 1 from public.user_lives where user_id=uid and life_id=p_actor_life_id) then raise exception 'inventory_transfer_actor_not_owned'; end if; if p_source_container_id=p_destination_container_id then raise exception 'inventory_transfer_same_container'; end if; if p_quantity is null or p_quantity<=0 then raise exception 'inventory_transfer_invalid_quantity'; end if; if not public.can_mutate_container(p_source_container_id,p_actor_life_id,'use') then raise exception 'inventory_transfer_source_not_authorized'; end if; if not public.can_mutate_container(p_destination_container_id,p_actor_life_id,'use') then raise exception 'inventory_transfer_destination_not_authorized'; end if; select * into v_item from public.items where id=p_item_id for share; if not found or v_item.status<>'active' then raise exception 'inventory_transfer_item_invalid'; end if; if not v_item.stackable then raise exception 'inventory_transfer_use_instance_path'; end if; select * into v_src from public.containers where id=least(p_source_container_id,p_destination_container_id) for update; select * into v_dst from public.containers where id=greatest(p_source_container_id,p_destination_container_id) for update; if v_src.id is null or v_dst.id is null then raise exception 'inventory_transfer_container_missing'; end if; select quantity into v_src_qty from public.inventory_entries where container_id=p_source_container_id and item_id=p_item_id and item_instance_id is null for update; if v_src_qty is null then raise exception 'inventory_transfer_source_item_missing'; end if; if v_src_qty<p_quantity then raise exception 'inventory_transfer_insufficient_quantity'; end if; select coalesce(quantity,0) into v_dst_qty from public.inventory_entries where container_id=p_destination_container_id and item_id=p_item_id and item_instance_id is null for update; if v_dst_qty+p_quantity>v_item.max_stack_size then raise exception 'inventory_transfer_stack_limit_exceeded'; end if; if v_dst.capacity is not null and (select coalesce(sum(quantity),0) from public.inventory_entries where container_id=p_destination_container_id)+p_quantity>v_dst.capacity then raise exception 'inventory_transfer_capacity_exceeded'; end if; return public.transfer_inventory(p_source_container_id,p_destination_container_id,p_item_id,p_quantity,p_actor_life_id,p_transfer_type,p_reason,p_metadata); end;$f$;
create or replace function public.transfer_inventory_instance_authorized(p_source_container_id uuid,p_destination_container_id uuid,p_item_instance_id uuid,p_actor_life_id uuid default null,p_transfer_type text default 'move',p_reason text default null,p_metadata jsonb default '{}') returns uuid language plpgsql security definer set search_path=public,pg_temp as $f$ begin if auth.uid() is null then raise exception 'inventory_instance_transfer_auth_required'; end if; if p_actor_life_id is null then raise exception 'inventory_instance_transfer_actor_required'; end if; if not exists(select 1 from public.user_lives ul where ul.user_id=auth.uid() and ul.life_id=p_actor_life_id) then raise exception 'inventory_instance_transfer_actor_not_owned'; end if; if not public.can_mutate_container(p_source_container_id,p_actor_life_id,'use') then raise exception 'inventory_instance_transfer_source_not_authorized'; end if; if not public.can_mutate_container(p_destination_container_id,p_actor_life_id,'use') then raise exception 'inventory_instance_transfer_destination_not_authorized'; end if; return public.transfer_inventory_instance(p_source_container_id,p_destination_container_id,p_item_instance_id,p_actor_life_id,p_transfer_type,p_reason,p_metadata); end;$f$;
create or replace function public.apply_item_durability_damage(p_item_instance_id uuid,p_damage numeric,p_cause text default 'unknown',p_metadata jsonb default '{}') returns public.item_instances language plpgsql set search_path=public,pg_temp as $f$ declare r public.item_instances%rowtype; v_container_id uuid; v_actor_life_id uuid; v_old_condition numeric; v_new_condition numeric; v_max numeric; v_old_broken boolean; v_new_broken boolean; begin if auth.uid() is null then raise exception 'inventory_durability_auth_required'; end if; if p_damage is null or p_damage<0 then raise exception 'damage must be >= 0'; end if; select ie.container_id into v_container_id from public.inventory_entries ie where ie.item_instance_id=p_item_instance_id limit 1; if v_container_id is null then raise exception 'item instance not currently in inventory'; end if; select ul.life_id into v_actor_life_id from public.user_lives ul where ul.user_id=auth.uid() and exists(select 1 from public.containers c where c.id=v_container_id and (c.owner_life_id=ul.life_id or public.can_mutate_container(c.id,ul.life_id,'use'))) limit 1; if v_actor_life_id is null then raise exception 'inventory_durability_not_authorized'; end if; select * into r from public.item_instances where id=p_item_instance_id for update; if not found then raise exception 'item instance % not found',p_item_instance_id; end if; v_max:=greatest(coalesce(r.max_durability,0),0); v_old_condition:=greatest(coalesce(r.condition,v_max),0); v_old_broken:=coalesce(r.is_broken,false); if p_damage=0 then return r; end if; v_new_condition:=greatest(0,v_old_condition-p_damage); v_new_broken:=v_new_condition<=0; update public.item_instances set condition=v_new_condition,is_broken=v_new_broken,updated_at=now() where id=p_item_instance_id returning * into r; insert into public.item_durability_history(item_instance_id,old_condition,new_condition,delta,old_is_broken,new_is_broken,cause,metadata) values(p_item_instance_id,v_old_condition,v_new_condition,v_new_condition-v_old_condition,v_old_broken,v_new_broken,coalesce(p_cause,'unknown'),coalesce(p_metadata,'{}')); return r; end;$f$;
create or replace function public.repair_item_instance(p_item_instance_id uuid,p_repair_amount numeric,p_cause text default 'repair',p_metadata jsonb default '{}') returns public.item_instances language plpgsql set search_path=public,pg_temp as $f$ declare r public.item_instances%rowtype; v_container_id uuid; v_actor_life_id uuid; v_old_condition numeric; v_new_condition numeric; v_max numeric; v_old_broken boolean; begin if auth.uid() is null then raise exception 'inventory_repair_auth_required'; end if; if p_repair_amount is null or p_repair_amount<0 then raise exception 'repair_amount must be >= 0'; end if; select ie.container_id into v_container_id from public.inventory_entries ie where ie.item_instance_id=p_item_instance_id limit 1; if v_container_id is null then raise exception 'item instance not currently in inventory'; end if; select ul.life_id into v_actor_life_id from public.user_lives ul where ul.user_id=auth.uid() and public.can_mutate_container(v_container_id,ul.life_id,'use') limit 1; if v_actor_life_id is null then raise exception 'inventory_repair_not_authorized'; end if; select * into r from public.item_instances where id=p_item_instance_id for update; if not found then raise exception 'item instance % not found',p_item_instance_id; end if; v_max:=greatest(coalesce(r.max_durability,0),0); v_old_condition:=greatest(coalesce(r.condition,0),0); v_old_broken:=coalesce(r.is_broken,false); v_new_condition:=least(v_max,v_old_condition+p_repair_amount); update public.item_instances set condition=v_new_condition,is_broken=(v_new_condition<=0),updated_at=now() where id=p_item_instance_id returning * into r; if v_new_condition<>v_old_condition then insert into public.item_durability_history(item_instance_id,old_condition,new_condition,delta,old_is_broken,new_is_broken,cause,metadata) values(p_item_instance_id,v_old_condition,v_new_condition,v_new_condition-v_old_condition,v_old_broken,(v_new_condition<=0),coalesce(p_cause,'repair'),coalesce(p_metadata,'{}')); end if; return r; end;$f$;
grant execute on function public.add_inventory_item_authorized(uuid,uuid,numeric,uuid,uuid,jsonb) to authenticated;
grant execute on function public.consume_inventory_item_authorized(uuid,uuid,numeric,uuid,uuid,text,jsonb) to authenticated;
grant execute on function public.transfer_inventory_authorized(uuid,uuid,uuid,numeric,uuid,text,text,jsonb) to authenticated;
grant execute on function public.transfer_inventory_instance_authorized(uuid,uuid,uuid,uuid,text,text,jsonb) to authenticated;
grant execute on function public.apply_item_durability_damage(uuid,numeric,text,jsonb) to authenticated;
grant execute on function public.repair_item_instance(uuid,numeric,text,jsonb) to authenticated;
revoke execute on function public.add_inventory_item_authorized(uuid,uuid,numeric,uuid,uuid,jsonb) from anon,public;
revoke execute on function public.consume_inventory_item_authorized(uuid,uuid,numeric,uuid,uuid,text,jsonb) from anon,public;
revoke execute on function public.transfer_inventory_authorized(uuid,uuid,uuid,numeric,uuid,text,text,jsonb) from anon,public;
